def transform(grid):
    # Keep only shapes that have horizontal and vertical symmetry (or specifically the 'H' / cross / 'I' like shape)
    # The 5 and 8 shapes are 3x3 shapes:
    # 1 0 1
    # 1 1 1
    # 1 0 1
    # This shape has 7 pixels. The 2 shape has 4 pixels.
    # Keep components with size == 7
    import copy
    R, C = len(grid), len(grid[0])
    out = [[0]*C for _ in range(R)]
    visited = set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                q = [(r, c)]
                visited.add((r, c))
                for cr, cc in q:
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                if len(comp) == 7:
                    for cr, cc in comp:
                        out[cr][cc] = color
    return out

