def transform(grid):
    # Keep shapes that appear more than once (by shape equivalence up to color)
    from collections import Counter
    R, C = len(grid), len(grid[0])
    visited = set()
    comps = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                q = [(r, c)]
                visited.add((r, c))
                for cr, cc in q:
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                min_r = min(p[0] for p in comp)
                min_c = min(p[1] for p in comp)
                norm_shape = frozenset((pr - min_r, pc - min_c) for pr, pc in comp)
                comps.append((comp, color, norm_shape))
    counts = Counter(s for _, _, s in comps)
    out = [[0]*C for _ in range(R)]
    for comp, color, s in comps:
        if counts[s] > 1:
            for cr, cc in comp:
                out[cr][cc] = color
    return out

