def transform(grid):
    # Remove the bottommost component
    R, C = len(grid), len(grid[0])
    visited = set()
    comps = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                q = [(r, c)]
                visited.add((r, c))
                for cr, cc in q:
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                comps.append((comp, color, max(p[0] for p in comp)))
    if not comps:
        return [[0]*C for _ in range(R)]
    max_bottom = max(b for _, _, b in comps)
    out = [[0]*C for _ in range(R)]
    for comp, color, b in comps:
        if b < max_bottom:
            for cr, cc in comp:
                out[cr][cc] = color
    return out
